export const industryStorageKey=(systemId,fixture=false)=>`space-project:industry:v1:${encodeURIComponent(systemId)}${fixture?':fixture':''}`;
export class IndustryStore {
 constructor(catalog,{storage=null,notify=()=>{},fixture=false,days=0}={}){this.catalog=catalog;this.storage=storage;this.notify=notify;this.key=industryStorageKey(catalog.systemId,fixture);this.blocked=false;this.error=null;this.raw=null;this.state=createIndustryState(catalog,days,{fixture});try{this.raw=storage?.getItem(this.key)??null;if(this.raw)this.state=validateIndustryState(parseSurfaceJSON(this.raw),catalog);}catch(e){this.blocked=true;this.error=e.message;notify('산업 저장 원본을 보존·격리했습니다. '+e.message);}}
 persist(){try{if(this.blocked)throw Error('손상/다른 버전 저장 원본 보존 중');validateIndustryState(this.state,this.catalog);if(!this.storage)throw Error('저장소 접근 불가');const text=JSON.stringify(this.state);this.storage.setItem(this.key,text);this.raw=text;this.error=null;return true;}catch(e){this.error=e.message;this.notify('산업 저장 실패: '+e.message+' · 캠페인 JSON을 내보내세요.');return false;}}
 preview(text){return structuredClone(validateIndustryState(parseSurfaceJSON(text),this.catalog));}
 replace(next){validateIndustryState(next,this.catalog);if(next.fixture!==this.state.fixture)throw Error('정식/개발 캠페인은 별도 저장입니다.');if(!this.storage)throw Error('교체 전 백업 저장소가 필요합니다.');const old=this.storage.getItem(this.key);if(old)this.storage.setItem(this.key+':backup',old);this.storage.setItem(this.key,JSON.stringify(next));this.state=structuredClone(next);this.blocked=false;this.error=null;this.raw=JSON.stringify(next);}
 export(){validateIndustryState(this.state,this.catalog);return JSON.stringify(this.state,null,2);}
}
